  const blank=useCallback(()=>emptyEntry(doctorId,profile.name,filterDate||today(),filterLoc||''),[doctorId,profile.name,filterDate,filterLoc]);

  useEffect(()=>{
    async function load(){
      try{
        const [logSnap,billingSnap,settingsSnap,completionSnap,feesSnap,codesSnap]=await Promise.all([
          getDocs(query(collection(db,'doctorLogs'),where('doctorId','in',[
            doctorId,
            doctorId.split(' ').pop(),
            doctorId.split(' ').pop().toLowerCase(),
            profile?.name || '',
          ].filter((v,i,a)=>v&&a.indexOf(v)===i).slice(0,10)))),
          getDocs(query(collection(db,'billingEntries'),where('doctorId','in',[
            doctorId,
            doctorId.split(' ').pop(),
            doctorId.split(' ').pop().toLowerCase(),
            doctorId.split(' ').pop().charAt(0).toUpperCase()+doctorId.split(' ').pop().slice(1).toLowerCase(),
            profile?.name || '',
            (profile?.name||'').split(' ').slice(-1)[0] || '',
          ].filter((v,i,a)=>v&&a.indexOf(v)===i).slice(0,10)))), // deduplicate, Firebase 'in' supports up to 30
          getDoc(doc(db,'billingSettings','otherItems')),
          getDoc(doc(db,'doctorCompletion',doctorId)),
          getDoc(doc(db,'billingSettings','fees')),
          getDoc(doc(db,'billingSettings','scheduleCodes'))
        ]);
        setEntries(logSnap.docs.map(d=>({id:d.id,...d.data()})));
        setBillingEntries(billingSnap.docs.map(d=>({id:d.id,...d.data()})));
        if(settingsSnap.exists()) setOtherItems(settingsSnap.data().items||[]);
        if(completionSnap.exists()) setCompletedDays(completionSnap.data().days||{});
        if(feesSnap.exists()) setFeeSettings(feesSnap.data());
        if(codesSnap.exists()&&codesSnap.data().codes) setScheduleCodes(codesSnap.data().codes);

      }catch(e){console.error(e);}
      setLoading(false);
    }
    load();

    // Real-time listener for billing entries — updates immediately when biller processes a patient
    const docIdVariants = [
      doctorId,
      doctorId.split(' ').pop(),
      doctorId.split(' ').pop().toLowerCase(),
      doctorId.split(' ').pop().charAt(0).toUpperCase()+doctorId.split(' ').pop().slice(1).toLowerCase(),
      profile?.name || '',
      (profile?.name||'').split(' ').slice(-1)[0] || '',
    ].filter((v,i,a)=>v&&a.indexOf(v)===i).slice(0,10);

    const unsub = onSnapshot(
      query(collection(db,'billingEntries'), where('doctorId','in',docIdVariants)),
      snap => setBillingEntries(snap.docs.map(d=>({id:d.id,...d.data()}))),
      err => console.error('billingEntries listener:', err)
    );
    return ()=>unsub();
  },[doctorId]);

